impl std::os::unix::io::AsRawFd for VirtualDevice {
    fn as_raw_fd(&self) -> std::os::unix::io::RawFd { self.file.as_raw_fd() }
}

impl std::os::unix::io::AsRawFd for Connection {
    fn as_raw_fd(&self) -> std::os::unix::io::RawFd {
        std::os::unix::io::AsRawFd::as_raw_fd(&self.inner)
    }
}
